// Debug the failing Step 3 transaction to find the device ID used
const { ethers } = require('ethers');

// Input data from failing transaction 0x60ca7a1ffc046b24d4cf900f71b8861872fb69ec1c1f4cac5ae6e941eebdee8e
const inputData = "";

console.log('🔍 Debugging Failed Step 3 Transaction\n');

// The function selector is the first 4 bytes (8 chars after 0x)
const functionSelector = inputData.slice(0, 10);
console.log('Function Selector:', functionSelector);

// For verifyDeviceProximity, the first parameter should be the device ID (bytes32)
// Skip function selector (4 bytes) and get the first 32 bytes
const deviceIdBytes32 = inputData.slice(10, 74);
const deviceIdHex = '0x' + deviceIdBytes32;

console.log('Device ID used in Step 3 verification:');
console.log('  Hex:', deviceIdHex);

// Let's also check the end of the input data where public inputs are
// The public inputs should be at the end - last 4 parameters
const inputLength = inputData.length;
console.log('Input data length:', inputLength);

// Extract last 4 uint256 values (32 bytes each = 64 hex chars each)
const publicInput1 = '0x' + inputData.slice(inputLength - 256, inputLength - 192);
const publicInput2 = '0x' + inputData.slice(inputLength - 192, inputLength - 128);
const publicInput3 = '0x' + inputData.slice(inputLength - 128, inputLength - 64);
const publicInput4 = '0x' + inputData.slice(inputLength - 64);

console.log('\nPublic Inputs (should match device ID and coordinates):');
console.log('  Input 1 (Device ID Hash):', publicInput1);
console.log('  Input 2 (Within Proximity):', publicInput2);
console.log('  Input 3 (X coordinate):', publicInput3, '=', parseInt(publicInput3, 16));
console.log('  Input 4 (Y coordinate):', publicInput4, '=', parseInt(publicInput4, 16));

console.log('\n🎯 Analysis:');
console.log('If Input 1 matches the Device ID, then the proof was generated correctly.');
console.log('If they don\'t match, there\'s a device ID inconsistency between registration and proof generation.');
console.log('');
console.log('Device ID in verification call:', deviceIdHex);
console.log('Device ID in public inputs:   ', publicInput1);
console.log('IDs match:', deviceIdHex === publicInput1 ? '✅ YES' : '❌ NO - INCONSISTENCY FOUND!');